import React, { useEffect, useRef } from 'react';

export default function ThreeSixtyViewer({ url, onClose }) {
  const viewerRef = useRef(null);

  useEffect(() => {
    if (!url) return;

    const initViewer = () => {
      if (window.pannellum && viewerRef.current) {
        // تنظيف الحاوية قبل الإنشاء لتجنب التكرار
        viewerRef.current.innerHTML = '';
        
        window.pannellum.viewer(viewerRef.current, {
          type: 'equirectangular',
          panorama: url,
          autoLoad: true,
          showControls: true,
          compass: false,
          title: 'جولة افتراضية',
        });
      }
    };

    if (!window.pannellum) {
      // تحميل ملفات CSS الخاصة بالمكتبة
      if (!document.getElementById('pannellum-css')) {
        const link = document.createElement('link');
        link.id = 'pannellum-css';
        link.rel = 'stylesheet';
        link.href = 'https://cdn.jsdelivr.net/npm/pannellum@2.5.6/build/pannellum.css';
        document.head.appendChild(link);
      }

      // تحميل ملف JS الخاص بالمكتبة
      const script = document.createElement('script');
      script.src = 'https://cdn.jsdelivr.net/npm/pannellum@2.5.6/build/pannellum.js';
      script.async = true;
      script.onload = initViewer;
      document.body.appendChild(script);
    } else {
      initViewer();
    }
  }, [url]);

  if (!url) return null;

  return (
    <div className="modal fade show d-block" tabIndex="-1" style={{ background: 'rgba(0,0,0,0.9)', zIndex: 1080 }}>
      <div className="modal-dialog modal-fullscreen">
        <div className="modal-content bg-transparent border-0 h-100">
          <div className="modal-header border-0 position-absolute top-0 end-0 p-4" style={{ zIndex: 10 }}>
            <button type="button" className="btn-close btn-close-white btn-lg shadow-none" onClick={onClose} style={{ filter: 'invert(1)' }}></button>
          </div>
          <div className="modal-body p-0 h-100 w-100">
             <div ref={viewerRef} style={{ width: '100%', height: '100%' }}></div>
          </div>
        </div>
      </div>
    </div>
  );
}
